// Additional chapter configurations are appended below to keep the data source reviewable.

function fmt(n){
  if(Object.is(n,-0)) n=0;
  const a=Math.abs(n);
  if(a===0)return '0';
  if(a>=1e4||a<1e-2){const e=Math.floor(Math.log10(a));const m=n/10**e;return `${Number(m.toPrecision(4))} × 10${String(e).replace('-','⁻').replace(/0/g,'⁰').replace(/1/g,'¹').replace(/2/g,'²').replace(/3/g,'³').replace(/4/g,'⁴').replace(/5/g,'⁵').replace(/6/g,'⁶').replace(/7/g,'⁷').replace(/8/g,'⁸').replace(/9/g,'⁹')}`;}
  return String(Number(n.toPrecision(5)));
}
const rotate=(arr,n)=>arr.slice(n).concat(arr.slice(0,n));
function uniqueTerms(concepts,i){return [concepts[i].term,...[1,5,11].map(d=>concepts[(i+d)%concepts.length].term)];}
function conceptQuestions(ch,c,i){
 const terms=uniqueTerms(ch.concepts,i), r=ref(ch.pdf,ch.base,c.page,c.section,c.context,c.extra||{}), img=c.visual?{src:`assets/questions/physics/${ch.slug}.svg`,alt:`Original educational schematic for ${ch.name}`,caption:`${ch.name} concept schematic`,pdfPage:c.page,printedPage:ch.base+c.page-1}:undefined;
 const common={topic:c.term,subtopic:c.section,ncertReference:r,ncertBasis:c.definition,references:[r]};
 const statementOptions=['Both Statement I and Statement II are true','Statement I is true but Statement II is false','Statement I is false but Statement II is true','Both Statement I and Statement II are false'];
 const arOptions=['Both A and R are true and R is the correct explanation of A','Both A and R are true but R is not the correct explanation of A','A is true but R is false','A is false but R is true'];
 const statementCases=[
  {a:c.definition,b:c.true2,answer:0,why:'Both statements are correct NCERT-based properties.'},
  {a:c.definition,b:c.false1,answer:1,why:`Statement I is correct, but Statement II is false. ${c.true2}`},
  {a:c.false1,b:c.true2,answer:2,why:`Statement I is false, while Statement II is correct. ${c.definition}`},
  {a:c.false1,b:c.false2,answer:3,why:`Both statements are false. The correct basis is: ${c.definition}`}
 ];
 const sc=statementCases[i%statementCases.length];
 const arCases=[
  {a:c.definition,b:c.true2,answer:1,why:'Both statements are true; R is a related property but is not the complete explanation of A.'},
  {a:c.definition,b:c.false1,answer:2,why:`A is true but R is false. ${c.true2}`},
  {a:c.false1,b:c.true2,answer:3,why:`A is false but R is true. The correct assertion basis is: ${c.definition}`}
 ];
 const ac=arCases[i%arCases.length];
 const next=ch.concepts[(i+1)%ch.concepts.length];
 const matchQuestion={...common,question:`Match ${c.term} and ${next.term} in List I with their descriptions in List II, then choose the correct code.`,options:['A–2, B–1','A–1, B–2','A–1, B–1','A–2, B–2'],answer:0,explanation:`A–2 because ${c.term}: ${c.definition} B–1 because ${next.term}: ${next.definition}`,questionType:'Match-the-column',table:{caption:`Match concepts from ${ch.name}`,headers:['List I','List II'],rows:[[ `A. ${c.term}`,`1. ${next.definition}`],[`B. ${next.term}`,`2. ${c.definition}`]]}};
 const applicationQuestion={...common,question:`A student encounters this situation: ${c.application} Which concept is most directly being applied?`,options:terms,answer:0,explanation:`The relevant concept is ${c.term}. ${c.definition} ${c.true3}`,questionType:'Application',image:img,...(chapters.indexOf(ch)>=8?{provenance:'NEET PYQ-style'}:{})};
 return [
  {...common,question:`Which term is described by the following NCERT-based statement? ${c.definition}`,options:terms,answer:0,explanation:`This is ${c.term}: ${c.definition} ${c.true2}`,questionType:'NCERT concept',image:img},
  {...common,question:`Which statement about ${c.term} is correct?`,options:[c.definition,c.false1,c.false2,c.false3],answer:0,explanation:`${c.definition} ${c.true2} The other choices contradict this definition or property.`,questionType:'Concept'},
  {...common,question:`Which statement is NOT consistent with ${c.term}?`,options:[c.true2,c.true3,c.definition,c.false1],answer:3,explanation:`The inconsistent statement is “${c.false1}” In contrast, ${c.definition}`,questionType:'Common misconception'},
  {...common,question:`Statement I: ${sc.a}\nStatement II: ${sc.b}`,options:statementOptions,answer:sc.answer,explanation:sc.why,questionType:'Statement I/II'},
  {...common,question:`Assertion (A): ${ac.a}\nReason (R): ${ac.b}`,options:arOptions,answer:ac.answer,explanation:ac.why,questionType:'Assertion–Reason'},
  i%10===9 && chapters.indexOf(ch)>=8?matchQuestion:applicationQuestion
 ];
}
function numericalOptions(value,unit,seed){
 const vals=[value,value*2,value/2,value*10];
 return rotate(vals.map(v=>`${fmt(v)} ${unit}`),seed%4);
}
function formulaQuestions(ch,f,i){
 const r=ref(ch.pdf,ch.base,f.page,f.section,f.context,{equationNumber:f.equationNumber});
 const common={topic:f.name,subtopic:f.section,ncertReference:r,ncertBasis:`NCERT relation: ${f.relation}.`,references:[r],formulaUsed:f.relation};
 const relationOptions=rotate([f.relation,...f.wrongRelations],i%4), relationAnswer=relationOptions.indexOf(f.relation);
 const numeric=(set,k)=>{const value=f.calc(set.v),opts=numericalOptions(value,f.unit,i+k),correct=`${fmt(value)} ${f.unit}`;const prompt=k===1?`Using ${f.name}, calculate the ${f.target} when ${set.given}.`:`A student applies ${f.relation} to a case where ${set.given}. Which value should be recorded for the ${f.target}?`;return {...common,question:prompt,options:opts,answer:opts.indexOf(correct),explanation:`Use ${f.relation}. Substitution of ${set.given} gives ${f.target} = ${correct}. Units and powers of ten have been retained in SI form.`,calculation:`${f.relation}; ${set.given}; result = ${correct}`,finalAnswer:correct,unit:f.unit,questionType:'Numerical'};};
 const unitAnswer=f.unitOptions.indexOf(f.unit);
 const table={caption:`Change in conditions for ${f.name}`,headers:['Case','Change','Required comparison'],rows:[['A','Original values',f.target],['B',f.scaleQuestion,`Value relative to case A`]]};
 return [
  {...common,question:`Which mathematical relation correctly represents ${f.name}?`,options:relationOptions,answer:relationAnswer,explanation:`The applicable NCERT relation is ${f.relation}. The alternatives contain an incorrect dependence or operation.`,questionType:'Formula'},
  numeric(f.sets[0],1),numeric(f.sets[1],2),
  {...common,question:f.scaleQuestion,options:f.scaleOptions,answer:f.scaleAnswer,explanation:`Apply the proportional dependence in ${f.relation}. Therefore the correct comparison is ${f.scaleOptions[f.scaleAnswer]}.`,questionType:'Data/table reasoning',table},
  {...common,question:`What is the SI unit of ${f.target} in the relation ${f.relation}?`,options:f.unitOptions,answer:unitAnswer,explanation:`Dimensional substitution in ${f.relation} gives the SI unit ${f.unit}.`,questionType:'Units and dimensions'},
  {...common,question:`Which is a common error to avoid while applying ${f.name}?`,options:[f.trap,'Using consistent SI units before substitution.','Checking the physical direction or sign separately from magnitude.','Verifying that the final unit matches the requested quantity.'],answer:0,explanation:`The identified trap is: ${f.trap} The other choices are valid quality-control steps, not errors.`,commonTrap:f.trap,questionType:'Common misconception',...(chapters.indexOf(ch)>=8?{provenance:'NEET PYQ-style'}:{})}
 ];
}
function difficulty(q){return q<=45?'Easy':q<=135?'Moderate':'Difficult';}
function buildChapter(ch){
 const fundamental=[],application=[],numerical=[],data=[],statements=[],mixed=[];
 ch.concepts.forEach((c,i)=>conceptQuestions(ch,c,i).forEach((q,v)=>({0:fundamental,1:fundamental,2:application,3:statements,4:statements,5:application}[v]).push(q)));
 ch.formulas.forEach((f,i)=>formulaQuestions(ch,f,i).forEach((q,v)=>({0:fundamental,1:numerical,2:numerical,3:data,4:mixed,5:mixed}[v]).push(q)));
 const all=[...fundamental,...application,...numerical,...data,...statements,...mixed];
 if(all.length!==180)throw new Error(`${ch.name}: generated ${all.length}, expected 180`);
 return all.map((q,i)=>({...q,id:`NEET-PHY12-${String(chapters.indexOf(ch)+1).padStart(2,'0')}-${String(i+1).padStart(3,'0')}`,questionNumber:i+1,chapter:ch.name,subject:'Physics',classLevel:12,difficulty:difficulty(i+1)}));
}

