  'electrostatic-potential-capacitance':['+Q','Equipotential','Capacitor'],
  'current-electricity':['Cell','R','Current I'],
  'moving-charges-magnetism':['v','B × × ×','F'],
  'magnetism-matter':['N','Magnetic field','S'],
  'electromagnetic-induction':['N →','Coil','Induced current'],
